    {
      "service": "geo",
      "fault_kind": "network_delay",
      "evidence": [
        {"kind": "trace", "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, approx_quantile(duration/1e6,0.95) p95_ms FROM abnormal_traces WHERE (service_name='search' AND span_name='geo.Geo/Nearby' AND attr_span_kind='Client') OR (service_name='geo' AND attr_span_kind='Server') GROUP BY ALL", "claim": "search's client spans to geo.Geo/Nearby have p95 about 2562 ms, while geo's server spans stay at about 0.24 ms."},
        {"kind": "trace", "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, approx_quantile(duration/1e6,0.95) p95_ms FROM normal_traces WHERE (service_name='search' AND span_name='geo.Geo/Nearby' AND attr_span_kind='Client') OR (service_name='geo' AND attr_span_kind='Server') GROUP BY ALL", "claim": "In the normal period search's client spans to geo had p95 about 0.6 ms, matching geo's server spans."},
        {"kind": "trace", "sql": "SELECT attr_span_kind, attr_http_request_method, count(*) n FROM abnormal_traces WHERE service_name='search' AND span_name='geo.Geo/Nearby' GROUP BY ALL", "claim": "The search-to-geo spans carry no HTTP attributes, so this is a gRPC transport-level connection delay."}
      ]
    }
  ],
  "propagation": [
    {"from": "geo", "to": "search",
     "evidence": [{"kind": "trace", "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, approx_quantile(duration/1e6,0.5) med_ms FROM abnormal_traces WHERE (service_name='search' AND span_name='search.Search/Nearby' AND attr_span_kind='Server') OR (service_name='search' AND span_name='geo.Geo/Nearby' AND attr_span_kind='Client') GROUP BY ALL", "claim": "search's server span for Nearby takes about 2570 ms, nearly all of it waiting on its geo client call (about 2560 ms)."}]},
    {"from": "search", "to": "frontend",
     "evidence": [{"kind": "trace", "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, approx_quantile(duration/1e6,0.95) p95_ms FROM abnormal_traces WHERE (service_name='frontend' AND span_name='search.Search/Nearby' AND attr_span_kind='Client') OR (service_name='frontend' AND span_name='HTTP /hotels' AND attr_span_kind='Server') GROUP BY ALL", "claim": "frontend's HTTP /hotels server spans have p95 about 2575 ms, mirroring the slow search Nearby client calls (about 2571 ms)."}]}
  ]
}
